parameters.jsCode:
const b = $json.body ?? {};

// En algunos casos, body puede venir como string JSON
let data = b;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch (e) { data = {}; }
}

const monitorName = data.monitor_name ?? 'N/A';
const monitorUrl  = data.monitor_url ?? 'N/A';

const statusRaw = (data.status ?? '').toString().toLowerCase();
// Si Uptime Kuma manda "up"/"down" o "1"/"0", lo cubrimos:
const isDown = statusRaw === 'down' || statusRaw === '0' || statusRaw === 'false';

const statusText = isDown ? 'DOWN ❌' : 'UP ✅';
const msg = data.msg ?? '';
const time = data.time ?? new Date().toISOString();

return [{
  json: {
    monitorName,
    monitorUrl,
    statusText,
    msg,
    time,
  }
}];
